package com.aaliyun.leadnews.article.service;
import com.aaliyun.leadnews.article.domain.ArticleSearchSync;import com.aaliyun.leadnews.article.mapper.ArticleSearchSyncMapper;import com.aaliyun.leadnews.common.trace.TraceContext;import com.aaliyun.leadnews.model.search.ArticleSearchEvent;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;import org.slf4j.*;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;import java.util.concurrent.TimeUnit;
@Service public class ArticleSearchOutboxService{private static final Logger log=LoggerFactory.getLogger(ArticleSearchOutboxService.class);private final ArticleSearchSyncMapper mapper;private final KafkaTemplate<String,ArticleSearchEvent> kafka;public ArticleSearchOutboxService(ArticleSearchSyncMapper m,KafkaTemplate<String,ArticleSearchEvent> k){mapper=m;kafka=k;}
 @Transactional public void enqueue(Long articleId,ArticleSearchEvent.EventType type){ArticleSearchSync x=new ArticleSearchSync();x.setEventId(UUID.randomUUID().toString());x.setArticleId(articleId);x.setEventType(type.name());x.setTraceId(TraceContext.getTraceId());x.setStatus("PENDING");x.setRetryCount(0);x.setNextRetryTime(LocalDateTime.now());mapper.insert(x);}
 @Scheduled(fixedDelayString="${leadnews.search-sync.retry-delay-ms:5000}") public void dispatch(){List<ArticleSearchSync> rows=mapper.selectList(new LambdaQueryWrapper<ArticleSearchSync>().in(ArticleSearchSync::getStatus,List.of("PENDING","FAILED")).le(ArticleSearchSync::getNextRetryTime,LocalDateTime.now()).lt(ArticleSearchSync::getRetryCount,10).orderByAsc(ArticleSearchSync::getId).last("LIMIT 100"));for(ArticleSearchSync row:rows)send(row);}
 private void send(ArticleSearchSync row){try{ArticleSearchEvent event=new ArticleSearchEvent(row.getEventId(),row.getArticleId(),ArticleSearchEvent.EventType.valueOf(row.getEventType()),row.getCreatedTime().atZone(ZoneId.systemDefault()).toInstant(),row.getTraceId());kafka.send("leadnews.article.search",row.getArticleId().toString(),event).get(10,TimeUnit.SECONDS);mapper.update(null,new LambdaUpdateWrapper<ArticleSearchSync>().eq(ArticleSearchSync::getId,row.getId()).set(ArticleSearchSync::getStatus,"SUCCESS").set(ArticleSearchSync::getLastError,null));}catch(Exception e){int retry=row.getRetryCount()+1;mapper.update(null,new LambdaUpdateWrapper<ArticleSearchSync>().eq(ArticleSearchSync::getId,row.getId()).set(ArticleSearchSync::getStatus,"FAILED").set(ArticleSearchSync::getRetryCount,retry).set(ArticleSearchSync::getNextRetryTime,LocalDateTime.now().plusSeconds(Math.min(300,1L<<Math.min(retry,8)))).set(ArticleSearchSync::getLastError,safe(e)));log.warn("Search event remains recoverable in outbox, eventId={}",row.getEventId());}}
 private String safe(Exception e){String m=e.getMessage();if(m==null)m=e.getClass().getSimpleName();return m.substring(0,Math.min(500,m.length()));}}
